    if err != nil {
        return User{}, err
    }
    var u User
    err = pool.QueryRow(ctx,
        `INSERT INTO users (email, password_hash) VALUES ($1, $2)
         RETURNING public_id, email`, email, string(hash),  // never the hash
    ).Scan(&u.PublicID, &u.Email)
